import { expect, test, uniqueName } from "../../fixtures";

const invalidFields = [
  { field: "name", value: "A" },
  { field: "category", value: "furniture" },
  { field: "contact_email", value: "not-an-email" },
] as const;

test.describe("Reject invalid vendor fields", () => {
  for (const { field, value } of invalidFields) {
    test(`rejects ${field} set to ${JSON.stringify(value)} with validation_error`, { tag: "@VEN-02" }, async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const payload: Record<string, unknown> = {
        name: uniqueName("Ven02 Vendor"),
        category: "software",
        contact_email: "billing@ven02.test",
      };
      payload[field] = value;

      // Act
      const res = await member.post("/api/vendors", { data: payload });

      // Assert
      const body = await res.text();
      expect(res.status(), body).toBe(422);
      const json = JSON.parse(body);
      expect(json.error.code, body).toBe("validation_error");
      const fields: string[] = (json.error.fields ?? []).map((f: { field: string }) => f.field);
      expect(fields, body).toContain(field);
    });
  }
});
